using System;
using System.Collections.Generic;
using System.IO;
using System.Text;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.DependencyInjection;

namespace MLInferenceServer
{
    public class FeatureFlags
    {
        private readonly Dictionary<string, bool> _flags = new();

        public FeatureFlags()
        {
            _flags["enhanced_logging"] = true;
            _flags["model_v2"] = false;
            _flags["structured_output"] = true;
            _flags["sanitize_model_names"] = true;
        }

        public bool IsEnabled(string flag) => _flags.TryGetValue(flag, out var v) && v;

        public string GetLoggingMode() => IsEnabled("enhanced_logging") ? "detailed" : "minimal";
    }

    public class ModelRegistry
    {
        private readonly Dictionary<string, Func<float[], float[]>> _models = new();

        public ModelRegistry()
        {
            _models["linear_v1"] = inputs => inputs;
            _models["neural_v1"] = inputs => { Array.Reverse(inputs); return inputs; };
        }

        public bool TryGetModel(string name, out Func<float[], float[]> model)
            => _models.TryGetValue(name, out model);

        public IEnumerable<string> ListModels() => _models.Keys;
    }

    public class InferenceLogger
    {
        private readonly ILogger<InferenceLogger> _logger;
        private readonly FeatureFlags _flags;

        public InferenceLogger(ILogger<InferenceLogger> logger, FeatureFlags flags)
        {
            _logger = logger;
            _flags = flags;
        }

        public void LogInferenceRequest(string modelName, string clientId, int featureCount)
        {
            if (_flags.GetLoggingMode() == "detailed")
            {
                var sanitized = SanitizeForLog(modelName);
                _logger.LogInformation(
                    "Inference request: model={Model}, client={Client}, features={Count}",
                    sanitized, SanitizeForLog(clientId), featureCount);
            }
        }

        public void LogModelResolution(string requestedName, string resolvedName, bool found)
        {
            if (_flags.GetLoggingMode() == "detailed")
            {
                _logger.LogInformation(
                    "Model resolution: requested={Requested}, resolved={Resolved}, found={Found}",
                    SanitizeForLog(requestedName), SanitizeForLog(resolvedName), found);
            }
        }

        private string SanitizeForLog(string input)
        {
            if (string.IsNullOrEmpty(input)) return "[empty]";
            var sb = new StringBuilder(input.Length);
            foreach (var c in input)
            {
                if (c >= 0x20 && c < 0x7F && c != '\\' && c != '"')
                    sb.Append(c);
                else
                    sb.Append('_');
            }
            return sb.ToString();
        }
    }

    public class InferenceMiddleware
    {
        private readonly RequestDelegate _next;

        public InferenceMiddleware(RequestDelegate next) => _next = next;

        public async Task InvokeAsync(HttpContext context, ModelRegistry registry,
            InferenceLogger inferenceLogger, FeatureFlags flags)
        {
            if (context.Request.Path.StartsWithSegments("/api/infer"))
            {
                var modelName = context.Request.Query["model"].ToString();
                var clientId = context.Request.Headers["X-Client-Id"].ToString();

                var resolvedName = ResolveModelName(modelName, flags);

                inferenceLogger.LogInferenceRequest(modelName, clientId, 0);
                inferenceLogger.LogModelResolution(modelName, resolvedName, 
                    registry.TryGetModel(resolvedName, out _));

                if (registry.TryGetModel(resolvedName, out var model))
                {
                    var result = model(new float[] { 1.0f, 2.0f, 3.0f });
                    await context.Response.WriteAsJsonAsync(new { prediction = result });
                }
                else
                {
                    context.Response.StatusCode = 404;
                    await context.Response.WriteAsJsonAsync(new { error = "Model not found" });
                }
                return;
            }
            await _next(context);
        }

        private string ResolveModelName(string input, FeatureFlags flags)
        {
            if (flags.IsEnabled("model_v2"))
                return input + "_v2";
            return NormalizeModelName(input);
        }

        private string NormalizeModelName(string input)
        {
            return input?.Trim().ToLowerInvariant() ?? "";
        }
    }

    public class AuditTrailWriter
    {
        private readonly string _auditPath;
        private readonly FeatureFlags _flags;

        public AuditTrailWriter(FeatureFlags flags)
        {
            _flags = flags;
            _auditPath = Path.Combine(AppContext.BaseDirectory, "audit.log");
        }

        public void WriteAuditEntry(string action, string subject, string detail)
        {
            var timestamp = DateTime.UtcNow.ToString("o");
            var entry = FormatAuditLine(timestamp, action, SanitizeForAudit(subject), SanitizeForAudit(detail));
            File.AppendAllText(_auditPath, entry + Environment.NewLine);
        }

        private string FormatAuditLine(string timestamp, string action, string subject, string detail)
        {
            if (_flags.IsEnabled("structured_output"))
            {
                return $"[{timestamp}] ACTION={action} SUBJECT={subject} DETAIL={detail}";
            }
            return $"{timestamp}|{action}|{subject}|{detail}";
        }

        private string SanitizeForAudit(string input)
        {
            if (string.IsNullOrEmpty(input)) return "[empty]";
            var sb = new StringBuilder(input.Length);
            foreach (var c in input)
            {
                if (c >= 0x20 && c < 0x7F && c != '\\' && c != '"' && c != '|' && c != '\n' && c != '\r')
                    sb.Append(c);
                else
                    sb.Append('_');
            }
            return sb.ToString();
        }
    }

    public class Program
    {
        public static void Main(string[] args)
        {
            var builder = WebApplication.CreateBuilder(args);
            builder.Services.AddSingleton<FeatureFlags>();
            builder.Services.AddSingleton<ModelRegistry>();
            builder.Services.AddSingleton<InferenceLogger>();
            builder.Services.AddSingleton<AuditTrailWriter>();

            var app = builder.Build();
            app.UseMiddleware<InferenceMiddleware>();
            app.Run();
        }
    }
}
